            if rc == AK_BDR_APPLY as i32 { break; }
            if fsm.len() > 4 * b.len() + 16 { bad = Some("runaway: more events than the input allows".into()); break; }
            rc = ak_fsm_next_ListResultsResponse(ctx, &mut ev);
            d.calls += 1;
